const msg = "[RT-DESKTOP-DISABLED] Opening local directory via desktop subprocess is not supported on Android mobile devices.";
console.error(msg);
try {
	if (window.RuntimePackWeb && typeof window.RuntimePackWeb.postDiagnosticError === "function") {
		window.RuntimePackWeb.postDiagnosticError(JSON.stringify({
			code: "RT-102",
			message: msg,
			capability: "CAP-WEB-028"
		}));
	}
} catch (_) {}
throw new Error(msg);
